select 'CARGA OK' resultado,p.id proyecto,p.responsable,p.objetivo_desde,p.objetivo_hasta,i.tipo,count(*) registros
from public.apertura_proyectos p join public.sucursales s on s.id=p.sucursal_id join public.apertura_items i on i.proyecto_id=p.id
where lower(trim(s.nombre))='dodo-2' group by p.id,i.tipo order by i.tipo;
